  // from causing SignatureDoesNotMatch when the runtime env has been rotated.
  const accessKeyId =
    readEnv('IVX_AWS_READONLY_ACCESS_KEY_ID') || readEnv('AWS_ACCESS_KEY_ID') || values.IVX_AWS_READONLY_ACCESS_KEY_ID || '';
