input.command:
cd /home/user/rork-app && echo "=== CHECK IF deploy failure is rate limit or commit-specific ===" && echo "Getting last successful deploy..." && TOKEN=$(cat /tmp/owner_token.txt 2>/dev/null) && curl -sS --max-time 15 "https://api.ivxholding.com/api/ivx/deploy-tools/render?action=deploys&limit=20" -H "Authorization: Bearer $TOKEN" 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const deploys = d.deploys || [];
console.log('Total deploys returned:', deploys.length);
// Find the last successful deploy
const successful = deploys.filter(dep => dep.status === 'live' || dep.status === 'build_in_progress' || dep.status === 'update_in_progress' || dep.status === 'created');
const failed = deploys.filter(dep => dep.status === 'build_failed' || dep.status === 'update_failed' || dep.status === 'canceled' || dep.status === 'deactivated');
console.log('Successful/active:', successful.length, '| Failed:', failed.length);
if (successful.length > 0) {
  const s = successful[0];
  console.log('Last successful:', s.id, '| status:', s.status, '| commit:', (s.commitSha||'').slice(0,8), '| created:', s.createdAt?.slice(11,19));
}
console.log('--- All deploys ---');
for (const dep of deploys) {
  console.log((dep.commitSha||'').slice(0,8), '|', dep.status, '|', dep.createdAt?.slice(11,19), '|', dep.duration+'s');
}
" 2>&1

